function area(k,hint){const value=state.fields[k]||'',field=k==='titel'?`<input type="text" id="${k}" data-field="${k}" maxlength="20000" value="${esc(value)}">`:`<textarea id="${k}" data-field="${k}" maxlength="20000">${esc(value)}</textarea>`;return `<details class="note-field"${value.trim()?' open':''}><summary data-note-label="${esc(fields[k])}">${value.trim()?'Notiz · '+esc(fields[k]):'Notiz hinzufügen · '+esc(fields[k])}</summary><label for="${k}">${esc(fields[k])}${hint?`<small>${esc(hint)}</small>`:''}</label>${field}<div class="print-only">${esc(value)}</div></details>`}
